// TH16 v1.00a Stage 2 midboss nonspell.
// source: st02mbs.ecl.txt MBoss:2-37 (entry), MBoss1:39-55, MBoss1_at:57-100,
//         default.ecl.txt Ecl_EtBreak_ni:174-190.
// Source timer: MBoss:23 setInterrupt(1,0,1500,"MBossDead"); timeout -> MBossEscape.
// Card frame = source frame + 124 (120 shell buffer + pattern/enemy task-start offsets).

const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;

const COLOR_LEFT: int = 4;   // MBoss1:46 MBoss1_at(0, 4, ...)
const COLOR_RIGHT: int = 6;  // MBoss1:48 MBoss1_at(1, 6, ...)

// Ecl_EtBreak_ni: MBoss:10 creates it at the parent FINAL (192,-32);
// r starts at 16, etClear(r) once per frame, r += 10 until r >= 640.
async sub et_break_sweep() {
    var r: fx = 16fx;
    while r < 640fx {
        clear_bullets_at(192fx, -32fx, r, 0);
        wait(1);
        r = r + 10fx;
    }
}

// MBoss body. Spawn position (192,-32) is the st02 main:1415 enmCreateA entry state.
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(24fx);   // MBoss:17 setHurtbox(48,48): 48*0.5
    set_hitbox(20fx);    // MBoss:18 setHitbox(40,40): 40*0.5
    spawn et_break_sweep();
    move_to(0, -192fx, -64fx, EASE_LINEAR);    // MBoss:26 movePos(-192,-64)
    move_to(100, 0fx, 128fx, EASE_QUAD_OUT);   // MBoss:27 movePosTime(100,4,0,128)
    wait(40);                                  // MBoss:28
    mboss1();                                  // MBoss:30 @MBoss1()
}

// MBoss1: wait(100), then loop { at(0) async; wait10; at(1) sync; wait30; moveRand; wait90 }.
sub mboss1() {
    wait(100);
    loop {
        spawn at_async(COLOR_LEFT, 0deg, 30deg, 0fx, 2fx);  // MBoss1:46 C=0 D=30deg E=0 F=2
        wait(10);
        at_sync(COLOR_RIGHT, 0deg, -20deg, 20fx, 2fx);     // MBoss1:48 C=0 D=-20deg E=20 F=2
        wait(30);
        move_rand();                                       // MBoss1:50 moveRand(80,4,1.0)
        card_wait(90);                                     // MBoss1:51
    }
}

// MBoss1_at with etNew(0)/etNew(1) emitters replaced by explicit per-bullet fire:
// etAim(0) aimed fan, etSprite(9,color), etCount(5,1), etAngle(alpha, 30deg),
// etSpeed(1.9/1.9/2.5/2.9), then per iteration:
// etOffsetRad(C,E); etAngle(RANDF2*4deg, 30deg + RANDF2*2deg); C+=D; E+=F (cap 82); etOn.
async sub at_async(color: int, c0: angle, d: angle, e0: fx, f: fx) {
    at_body(color, c0, d, e0, f);
}

sub at_sync(color: int, c0: angle, d: angle, e0: fx, f: fx) {
    at_body(color, c0, d, e0, f);
}

sub at_body(color: int, c0: angle, d: angle, e0: fx, f: fx) {
    var speed: fx = 2.9fx;   // !LO
    var iters: int = 8000;   // MBoss1_at:77 diffI(15,40,80,8000)
    var gap: int = 4;        // MBoss1_at:87-96 wait(20,20,10,4)
    var rk: int = global(GVAR_RANK);
    if rk == RANK_EASY {
        speed = 1.9fx;
        iters = 15;
        gap = 20;
    } else if rk == RANK_NORMAL {
        speed = 1.9fx;
        iters = 40;
        gap = 20;
    } else if rk == RANK_HARD {
        speed = 2.5fx;
        iters = 80;
        gap = 10;
    }
    var c: angle = c0;
    var e: fx = e0;
    var n: int = 0;
    while n < iters {
        var mx: fx = $self_x + e * cos(c);   // MBoss1_at:80 etOffsetRad(C,E)
        var my: fx = $self_y + e * sin(c);
        var aim: int = atan2($player_y - my, $player_x - mx) as int;
        var u1: fx = (rand(65536) - 32768) as fx / 32768;
        var alpha: int = (728fx * u1) as int;         // RANDF2 * 0.06981317rad
        var u2: fx = (rand(65536) - 32768) as fx / 32768;
        var delta: int = 5461 + (364fx * u2) as int;  // 30deg + RANDF2 * 0.034906585rad
        // MBoss1_at:81 fan order F(5,i) = 0, -1, +1, -2, +2 times delta.
        for i in 0..5 {
            var h: int = (i + 1) / 2;
            if i % 2 == 1 { h = -h; }
            var a: angle = (aim + alpha + h * delta) as angle;
            var vx: fx = speed * cos(a);
            var vy: fx = speed * sin(a);
            // ANIM (etEx type2 a=1) birth animation omitted; its position -= 4*velocity kept.
            _ = fire(TH16_KUNAI, color, mx - 4fx * vx, my - 4fx * vy, speed, a, none, none);
        }
        c = c + d;
        if e <= 80fx { e = e + f; }
        wait(gap);
        n = n + 1;
    }
}

// moveRand(80,4,1.0) sample from transcribe/th16/movement.md with this card's
// moveLimit(0,128,280,256): clamp x[-140,140] y[0,256], inner region x+-70 y[64,192].
// int slot 0 = next step count, fx slots 0/1 = logical unit vector.
sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}

sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var sp: fx = 0fx;
    if k < 80 { sp = (80 - k) as fx / 80; }
    var nx: fx = $self_x + self_fx(0) * sp;
    var ny: fx = $self_y + self_fx(1) * sp;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(192fx, -32fx, 11000, 0, 0, 0, boss_main);  // MBoss lifeSet(11000)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

